const fs=require('fs'),path=require('path'),{execFileSync}=require('child_process');
const R='/workspace/scratch/216787930017',S=path.join(R,'party8b_source/8b_q02_q06'),W=path.join(R,'party8b_work'),O=path.join(R,'party8b_generated');
const rec=[];
function im(a,input){return execFileSync('/usr/bin/convert',a,{input,maxBuffer:80*1024*1024});}
function save(p,b){const f=fs.openSync(p,'w');try{fs.writeFileSync(f,b);fs.fsyncSync(f);}finally{fs.closeSync(f);}}
function sprite(f,size,x,y,extra=[]){return ['(',path.join(W,f),'-channel','A','-black-threshold','1%','+channel','-trim','+repage',...extra,'-resize',size,')','-geometry',`+${x}+${y}`,'-compose','Over','-composite'];}
function layer(n,base,args){const h=base==='O1_bg.png'?940:941;save(path.join(O,n),im(['-size',`1672x${h}`,'xc:none',...args,'-depth','8','PNG32:-']));rec.push({name:n,base,width:1672,height:h,origin:[0,0],scale:1});}
for(const n of ['closeup_village_map_old.png','closeup_second_bench.png']){save(path.join(O,n),im([path.join(O,n),'-resize','1672x941!','-alpha','off','-depth','8','PNG24:-']));rec.push({name:n,base:null,width:1672,height:941});}
// Keep the original drawing coordinates and map the formerly fenced plot's four corners to the empty plot.
save(path.join(W,'garden_registered.png'),im([path.join(W,'garden_pencil_clean_raw.png'),'-channel','A','-black-threshold','1%','-evaluate','multiply','0.70','+channel','-virtual-pixel','transparent','-define','distort:viewport=1672x941+0+0','-distort','Perspective','270,360 1247,519 1065,140 1454,495 1410,738 1503,668 558,940 1296,695','+repage','-depth','8','PNG32:-']));
// Trim the generation's stray outer halo; retain the paper texture, then make the sheet translucent.
save(path.join(W,'tracing_paper_clean.png'),im([path.join(W,'tracing_paper_raw.png'),'-crop','1570x850+48+45','+repage','-alpha','set','-channel','A','-evaluate','set','18%','+channel','-depth','8','PNG32:-']));
layer('closeup_village_map_tracing.png','closeup_village_map_old.png',[
 '(',path.join(W,'tracing_paper_clean.png'),'-resize','1480x840!',')','-geometry','+100+45','-composite',
 path.join(W,'garden_registered.png'),'-geometry','+0+0','-composite'
]);
// Same hanging map for both school views. Only the tracing is added for the epilogue.
layer('O1_state_village_map.png','O1_bg.png',sprite('map_hanging_raw.png','180x104!',883,444));
save(path.join(W,'map_tracing_wall_raw.png'),im([path.join(W,'map_hanging_raw.png'),'(',path.join(O,'closeup_village_map_tracing.png'),'-resize','1640x890!',')','-geometry','+18+37','-composite','-depth','8','PNG32:-']));
layer('ep_lesson_map.png','ep_lesson.png',sprite('map_tracing_wall_raw.png','180x104!',883,444));
// Small tracing drawing at dinner, with a pin mechanically cropped from the original map.
save(path.join(W,'map_pin.png'),im([path.join(O,'closeup_village_map_old.png'),'-crop','50x50+78+24','+repage','(','-size','50x50','xc:black','-fill','white','-draw','circle 25,25 46,25',')','-alpha','off','-compose','CopyOpacity','-composite','PNG32:-']));
layer('ep_dinner_ulyana_map.png','ep_dinner.png',[
 '(',path.join(W,'tracing_paper_clean.png'),'-channel','A','-evaluate','multiply','2.6','+channel','-resize','85x63!',')','-geometry','+997+151','-composite',
 ...sprite('garden_pencil_clean_raw.png','62x45!',1009,164),
 ...sprite('map_pin.png','6x6!',1035,151)
]);
layer('ep_dinner_photo_frame.png','ep_dinner.png',sprite('photo_frame_raw.png','59x72!',626,256));
layer('H2_state_second_bench.png','H2_bg.png',sprite('bench_endview_raw.png','142x190!',1221,410,['-modulate','84,92,100']));
// Existing bell stand is in front of the far bench. Do not let the new object cover its left edge.
save(path.join(W,'bell_occlusion_mask.png'),im(['-size','1672x941','xc:white','-fill','black','-draw','polygon 1345,463 1612,471 1644,641 1510,644 1500,515 1425,506 1365,610 1325,608','-depth','8','png:-']));
save(path.join(O,'H2_state_second_bench.png'),im([path.join(O,'H2_state_second_bench.png'),'(',path.join(O,'H2_state_second_bench.png'),'-alpha','extract',path.join(W,'bell_occlusion_mask.png'),'-compose','Multiply','-composite',')','-alpha','off','-compose','CopyOpacity','-composite','-depth','8','PNG32:-']));
layer('ep_boat_bench.png','ep_boat.png',sprite('boat_bench_corrected_raw.png','420x230!',1230,697));
// Return the edited annex crop to exactly the crop's original coordinates, then retain only its opening.
save(path.join(W,'annex_registered.png'),im(['-size','1672x941','xc:none','(',path.join(W,'annex_bench_crop_full.png'),'-resize','500x282!',')','-geometry','+1120+330','-composite','PNG32:-']));
save(path.join(W,'annex_mask.png'),im(['-size','1672x941','xc:black','-fill','white','-draw','polygon 1404,421 1479,430 1480,516 1406,523','-blur','0x1','-black-threshold','1%','-depth','8','png:-']));
save(path.join(O,'O4_state_bench_shed.png'),im([path.join(W,'annex_registered.png'),path.join(W,'annex_mask.png'),'-alpha','off','-compose','CopyOpacity','-composite','-depth','8','PNG32:-']));
rec.push({name:'O4_state_bench_shed.png',base:'O4_bg.png',width:1672,height:941,origin:[0,0],scale:1});
for(const r of rec.filter(x=>x.base)){
 const base=path.join(r.base.startsWith('closeup_')?O:S,r.base);
 save(path.join(O,'PREVIEWS',r.name.replace('.png','_over_base.jpg')),im([base,path.join(O,r.name),'-compose','Over','-composite','-quality','94','jpeg:-']));
}
save(path.join(W,'export_records.json'),Buffer.from(JSON.stringify(rec,null,2)));
console.log(JSON.stringify({files:rec.length,layers:rec.filter(r=>r.base).length}));
